<?php
declare(strict_types=1);
use Vendi\Database\Connection;
require dirname(__DIR__,3).'/vendor/autoload.php';session_start();$u=$_SESSION['user']??null;if(!$u){http_response_code(401);exit;}
$db=Connection::make(['host'=>getenv('DB_HOST')?:'127.0.0.1','port'=>(int)(getenv('DB_PORT')?:3306),'database'=>getenv('DB_DATABASE')?:'vendi','username'=>getenv('DB_USERNAME')?:'root','password'=>getenv('DB_PASSWORD')?:'']);
$q=$db->prepare("SELECT s.*,b.name branch_name,u.name user_name FROM sales s JOIN branches b ON b.id=s.branch_id JOIN users u ON u.id=s.user_id WHERE s.id=? AND s.business_id=?");$q->execute([(int)($_GET['id']??0),(int)$u['business_id']]);$s=$q->fetch();if(!$s){http_response_code(404);exit('Venta no encontrada');}$i=$db->prepare("SELECT description,qty,unit_price,line_total FROM sale_items WHERE sale_id=?");$i->execute([$s['id']]);$items=$i->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><style>@page{size:80mm auto;margin:3mm}body{font:12px monospace;width:72mm;margin:auto}h1,p{text-align:center}table{width:100%}.r{text-align:right}.total{font-size:16px;font-weight:bold}@media print{button{display:none}}</style></head><body><h1>Vendi POS</h1><p><?=htmlspecialchars($s['branch_name'])?><br>Venta #<?=$s['id']?> · <?=htmlspecialchars($s['completed_at'])?></p><table><?php foreach($items as $x):?><tr><td><?=htmlspecialchars($x['description'])?><br><?=$x['qty']?> × $<?=number_format((float)$x['unit_price'],2)?></td><td class="r">$<?=number_format((float)$x['line_total'],2)?></td></tr><?php endforeach;?><tr><td>Subtotal</td><td class="r">$<?=number_format((float)$s['subtotal'],2)?></td></tr><tr><td>IVA</td><td class="r">$<?=number_format((float)$s['tax'],2)?></td></tr><tr class="total"><td>TOTAL</td><td class="r">$<?=number_format((float)$s['total'],2)?></td></tr></table><p>Gracias por su compra</p><button onclick="print()">Imprimir</button></body></html>